import os
import pytest
from envcfg import load, EnvCfgError


def _env(prefix: str, **kwargs) -> dict:
    """Helper to build an env dict with the given prefix and values."""
    env = {}
    for key, value in kwargs.items():
        env[f"{prefix}__{key}"] = str(value)
    return env


def _defaults(**kwargs) -> dict:
    """Helper to build a defaults dict."""
    return dict(kwargs)


def test_defaults_only():
    cfg = load(_defaults(a=1, b=2))
    assert cfg == {"a": 1, "b": 2}


def test_defaults_override_by_toml():
    cfg = load(_defaults(a=1), toml_path="tests/data/config.toml")
    assert cfg == {"a": 10, "b": 2}


def test_defaults_override_by_env():
    cfg = load(_defaults(a=1), env=_env("APP", a=20))
    assert cfg == {"a": 20, "b": 2}


def test_toml_override_defaults():
    cfg = load(_defaults(a=1), toml_path="tests/data/config.toml")
    assert cfg == {"a": 10, "b": 2}


def test_env_override_toml():
    cfg = load(_defaults(a=1), toml_path="tests/data/config.toml", env=_env("APP", a=20))
    assert cfg == {"a": 20, "b": 2}


def test_nested_defaults():
    cfg = load(_defaults(server={"port": 8080, "host": "localhost"}))
    assert cfg == {"server": {"port": 8080, "host": "localhost"}}


def test_nested_toml():
    cfg = load(_defaults(server={"port": 8080}), toml_path="tests/data/config.toml")
    assert cfg == {"server": {"port": 9000, "host": "0.0.0.0"}}


def test_nested_env():
    cfg = load(_defaults(server={"port": 8080}), env=_env("APP", server__port=9000))
    assert cfg == {"server": {"port": 9000, "host": "localhost"}}


def test_nested_all_layers():
    cfg = load(_defaults(server={"port": 8080}), toml_path="tests/data/config.toml", env=_env("APP", server__port=9000))
    assert cfg == {"server": {"port": 9000, "host": "0.0.0.0"}}


def test_int_coerce():
    cfg = load(_defaults(port=80), env=_env("APP", port="9000"))
    assert cfg == {"port": 9000}


